class Ingredient {
  final String name;
  final String quantity;
  const Ingredient(this.name, this.quantity);
}

class Recipe {
  final int id;
  final String title;
  final List<Ingredient> ingredients;
  final String notes;
  final int calories;
  final int servings;
  const Recipe({
    required this.id,
    required this.title,
    required this.ingredients,
    required this.notes,
    this.calories = 575,
    this.servings = 1,
  });

  List<String> get steps {
    final parts = notes.split(RegExp(r'(?<=[.!])\s+'));
    return parts.where((p) => p.trim().isNotEmpty).toList();
  }
}

